INSERT INTO entries (category_id, title, summary, content, location, event_date, image_url, source_url)
SELECT id, v.title, v.summary, v.content, v.location, v.event_date, v.image_url, v.source_url
FROM categories c,
LATERAL (VALUES
  ('San Juan (El Espinal)', 'Em 2022, em San Juan, Honduras, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Por volta das 17h de 9 de junho de 2022, o ministro extraordinário José Elmer Benítez Machado encontrou um corporal manchado de sangue dentro do sacrário da capela comunitária de El Espinal, em San Juan, Honduras. Exames laboratoriais realizados no país confirmaram tratar-se de sangue humano do tipo AB+. Dom Walter Guillén Soto, bispo da Diocese de Gracias, reconheceu o caso como milagre eucarístico e o encaminhou ao Vaticano para avaliação.', 'San Juan, Honduras', '2022', NULL, 'https://eucharisticmiracles.faith/miracle/hon-san-juan-2022'),
  ('Legnica', 'Em 2013, em Legnica, Polônia, exames posteriores identificaram tecido compatível com músculo cardíaco humano.', 'No dia de Natal de 2013, uma hóstia consagrada caiu acidentalmente durante a missa na Igreja de São Jacinto, em Legnica, na Polônia. Seguindo o protocolo da Igreja, ela foi colocada em água para se dissolver, mas em vez disso desenvolveu uma mancha vermelha. Duas universidades polonesas analisaram o material e encontraram fragmentos de tecido semelhantes a músculo cardíaco humano, com alterações típicas de agonia; o sequenciamento mitocondrial indicou DNA humano, ainda que o material estivesse degradado.', 'Legnica, Polônia', '2013', NULL, 'https://eucharisticmiracles.faith/miracle/pol-legnica'),
  ('Vilakkannur', 'Em 2013, em Vilakkannur, Índia, testemunhas relataram ter visto um rosto ou imagem de Cristo na hóstia exposta.', 'Em 15 de novembro de 2013, durante a missa na Igreja de Cristo Rei, em Vilakkannur, no estado indiano de Kerala, o padre Thomas Pathickal observou o rosto de Jesus Cristo aparecer sobre a hóstia no momento da consagração. Depois de mais de onze anos de investigação, o Dicastério para a Doutrina da Fé não encontrou objeções para declará-lo sinal eucarístico extraordinário em 19 de março de 2025, e o núncio apostólico proclamou o reconhecimento na paróquia em 31 de maio de 2025.', 'Vilakkannur, Índia', '2013', NULL, 'https://eucharisticmiracles.faith/miracle/ind-vilakkannur-2013'),
  ('Sokółka', 'Em 2008, em Sokółka, Polônia, exames posteriores identificaram tecido compatível com músculo cardíaco humano.', 'Durante a missa na Igreja de Santo Antônio de Pádua, um padre deixou cair acidentalmente uma hóstia consagrada, que foi colocada em água para se dissolver, como manda o protocolo litúrgico. Uma semana depois, a irmã Julia Dubowska percebeu que a hóstia não havia se dissolvido e que haviam surgido manchas vermelhas em seu centro. Análises científicas identificaram o que parecia ser tecido muscular cardíaco com sinais de trauma.', 'Sokółka, Polônia', '2008', NULL, 'https://eucharisticmiracles.faith/miracle/pol-sokolka'),
  ('Tixtla', 'Em 2006, em Tixtla, México, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Durante um retiro espiritual com 600 participantes, uma hóstia consagrada começou a exsudar uma substância avermelhada no momento da distribuição da Comunhão. Uma investigação conduzida entre 2009 e 2012 pelo médico Ricardo Castañón relatou a presença de sangue humano tipo AB e tecido de músculo cardíaco, mas os resultados nunca foram publicados em revista científica revisada por pares e são contestados por peritos forenses; o processo diocesano segue incompleto e Roma não aprovou o caso.', 'Tixtla, México', '2006', NULL, 'https://eucharisticmiracles.faith/miracle/mex-tixtla'),
  ('Chirattakonam', 'Em 2001, em Chirattakonam (Trivandrum), Índia, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Durante a novena anual a São Judas Tadeu, três pontos surgiram sobre uma hóstia consagrada exposta à adoração e, ao longo de uma semana, foram se transformando em um rosto semelhante ao de Cristo coroado de espinhos. A imagem ficou mais nítida justamente no dia em que se lia, na liturgia, a passagem do Evangelho de João sobre o apóstolo Tomé duvidando da Ressurreição.', 'Chirattakonam (Trivandrum), Índia', '2001', NULL, 'https://eucharisticmiracles.faith/miracle/chirattakonam-2001'),
  ('Buenos Aires', 'Em 1996, em Buenos Aires, Argentina, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Uma hóstia caída durante a distribuição da Comunhão foi recolhida e, seguindo o costume de dissolvê-la em água, passou a apresentar o que parecia ser tecido sanguinolento. O médico Frederick Zugibe analisou o material e descreveu sinais compatíveis com músculo cardíaco humano inflamado, mas o estudo nunca foi publicado com revisão por pares, e a Igreja nunca declarou oficialmente o caso como milagre.', 'Buenos Aires, Argentina', '1996', NULL, 'https://eucharisticmiracles.faith/miracle/arg-buenos-aires'),
  ('Betania Cúa', 'Em 1991, em Cúa, Venezuela, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Durante a missa da meia-noite de 8 de dezembro de 1991, no santuário mariano da Finca Betania, perto de Cúa, na Venezuela, o padre Otty Ossa Aristizábal viu uma hóstia consagrada começar a sangrar. Testes científicos confirmaram tratar-se de sangue humano do tipo AB positivo. A hóstia é conservada até hoje no convento agostiniano de Los Teques.', 'Cúa, Venezuela', '1991', NULL, 'https://eucharisticmiracles.faith/miracle/ven-betania'),
  ('San Mauro La Bruca', 'Em 1969, em San Mauro La Bruca, Itália, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Em 25 de julho de 1969, hóstias que haviam sido roubadas e profanadas foram encontradas na Itália e, desde então, permanecem preservadas sem qualquer sinal de decomposição — já são mais de cinquenta anos de conservação inexplicada.', 'San Mauro La Bruca, Itália', '1969', NULL, 'https://eucharisticmiracles.faith/miracle/ita-san-mauro-la-bruca'),
  ('Rosano', 'Em 1948, em Rosano, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1948, uma imagem do Sagrado Coração de Jesus sangrou e chorou dentro da igreja de um mosteiro italiano. Análises médicas do material recolhido na época foram preservadas nos arquivos da comunidade religiosa.', 'Rosano, Itália', '1948', NULL, 'https://eucharisticmiracles.faith/miracle/ita-rosano'),
  ('Blessed Alexandrina Maria da Costa - Eucharistic Sustenance Balasar', 'Em 1942-1955, em Balasar, Portugal, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'A mística portuguesa Alexandrina Maria da Costa passou 13 anos alimentando-se apenas da Eucaristia, sem nenhum outro alimento ou bebida. Em 1943, médicos a mantiveram sob observação contínua durante 40 dias e não registraram nenhuma ingestão de comida ou líquido, nem qualquer tipo de excreção — um fenômeno que a ciência da época não conseguiu explicar.', 'Balasar, Portugal', '1942-1955', NULL, 'https://eucharisticmiracles.faith/miracle/alexandrina-maria-da-costa-eucharistic-sustenance'),
  ('Divine Mercy Apparitions to St. Faustina Kowalska Kraków', 'Em 1931, em Kraków, Polônia, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Jesus apareceu à religiosa polonesa Santa Faustina Kowalska mostrando o próprio Coração, do qual saíam dois raios — um vermelho e um pálido — representando o Sangue e a Água derramados de seu lado na cruz. Dessas visões nasceu a devoção à Divina Misericórdia, hoje uma das mais difundidas da Igreja Católica.', 'Kraków, Polônia', '1931', 'https://commons.wikimedia.org/wiki/Special:FilePath/Church_of_Divine_Mercy%2C_3_Siostry_Faustyny_street%2C_%C5%81agiewniki%2C_Krak%C3%B3w_Poland.jpg', 'https://eucharisticmiracles.faith/miracle/divine-mercy-apparitions-cracow'),
  ('Marthe Robin''s Eucharistic Sustenance Châteauneuf-de-Galaure', 'Em 1930, em Châteauneuf-de-Galaure, França, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'A francesa Marthe Robin passou 53 anos sem comer nem beber, sustentada apenas pela Comunhão, enquanto vivenciava semanalmente os estigmas da Paixão de Cristo e outros fenômenos místicos observados por quem a visitava.', 'Châteauneuf-de-Galaure, França', '1930', NULL, 'https://eucharisticmiracles.faith/miracle/marthe-robin-eucharistic-sustenance'),
  ('Teresa Neumann''s Eucharistic Sustenance Konnersreuth', 'Em 1926, em Konnersreuth, Alemanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'A alemã Teresa Neumann viveu 36 anos alimentando-se somente da Sagrada Eucaristia, apresentando estigmas e revivendo, toda semana, os sofrimentos da Paixão de Cristo.', 'Konnersreuth, Alemanha', '1926', NULL, 'https://eucharisticmiracles.faith/miracle/teresa-neumann-eucharistic-sustenance'),
  ('The Angel of Peace Fatima', 'Em 1916, em Fatima, Portugal, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Um ano antes das aparições marianas de Fátima, um anjo identificado como o Anjo da Paz apareceu três vezes aos três pastorinhos e, numa das visitas, deu-lhes a Comunhão com uma hóstia da qual caíam gotas de sangue dentro do cálice.', 'Fatima, Portugal', '1916', 'https://commons.wikimedia.org/wiki/Special:FilePath/First_Sculpture_of_Our_Lady_of_Fatima.jpg', 'https://eucharisticmiracles.faith/miracle/fatima-angel-of-peace-1916'),
  ('Silla', 'Em 1907, em Silla, Espanha, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Hóstias roubadas de uma paróquia valenciana em 1907 foram recuperadas intactas e, segundo os registros locais, permanecem incorruptas há mais de um século.', 'Silla, Espanha', '1907', NULL, 'https://eucharisticmiracles.faith/miracle/spa-silla'),
  ('Tumaco', 'Em 1906, em Tumaco, Colômbia, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Em 31 de janeiro de 1906, quando um tsunami avançava sobre a cidade colombiana de Tumaco, o padre Gerardo Larrondo ergueu o Santíssimo Sacramento na direção do mar. Testemunhas relataram que a onda perdeu força e recuou, e a tradição local atribui a esse gesto o fato de a cidade ter sido poupada.', 'Tumaco, Colômbia', '1906', NULL, 'https://eucharisticmiracles.faith/miracle/col-tumaco'),
  ('Morne-Rouge', 'Em 1902, em Morne-Rouge, França, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'A vila de Morne-Rouge, na Martinica, foi poupada pela mesma erupção vulcânica que destruiu completamente a cidade de Saint-Pierre. Fiéis do local relataram ter visto o Sagrado Coração de Cristo aparecer na hóstia durante as celebrações daqueles dias.', 'Morne-Rouge, França', '1902', NULL, 'https://eucharisticmiracles.faith/miracle/morne-rouge-1902'),
  ('Saint-André de la Réunion', 'Em 1902, em Saint-André, França (Ilha da Reunião), testemunhas relataram ter visto um rosto ou imagem de Cristo na hóstia exposta.', 'Durante a missa na Ilha da Reunião, o pároco viu o rosto de Jesus aparecer sobre a hóstia e chamou as crianças do coral para confirmar o que via; milhares de fiéis relataram ter testemunhado a mesma imagem nos dias seguintes.', 'Saint-André, França (Ilha da Reunião)', '1902', NULL, 'https://eucharisticmiracles.faith/miracle/saint-andre-de-la-reunion-1902'),
  ('Eucharistic Healing Miracles of Lourdes Lourdes', 'Em 1888, em Lourdes, França, o episódio está associado a uma cura considerada extraordinária.', 'Desde 1888, o santuário de Lourdes registra curas consideradas inexplicáveis pela medicina, associadas às procissões com o Santíssimo Sacramento que acontecem regularmente no local até os dias de hoje.', 'Lourdes, França', '1888', 'https://commons.wikimedia.org/wiki/Special:FilePath/Grotto_of_Massabielle_Lourdes.jpg', 'https://eucharisticmiracles.faith/miracle/lourdes-eucharistic-procession-1888'),
  ('Peshtigo', 'Em 1871, em Peshtigo, Estados Unidos, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Durante o incêndio de Peshtigo, em 1871 — considerado até hoje o incêndio florestal mais mortal da história dos Estados Unidos —, o padre Peter Pernin conseguiu salvar o sacrário de madeira de sua igreja, com o Santíssimo Sacramento dentro, puxando-o numa carroça até o Rio Peshtigo. Na manhã seguinte, o sacrário foi encontrado intacto e branco em meio à destruição total da cidade, incluindo pontes e prédios de pedra. O próprio padre relatou o episódio em suas memórias de 1874, mas evitou, com cautela, chamá-lo de milagre.', 'Peshtigo, Estados Unidos', '1871', NULL, 'https://eucharisticmiracles.faith/miracle/usa-peshtigo'),
  ('Anne-Louise Lateau Eucharistic Fasting and Stigmata Bois-d''Haine', 'Em 1868-1871, em Bois-d''Haine, Bélgica, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'A mística belga Anne-Louise Lateau teria vivido doze anos alimentando-se somente da Eucaristia. A Academia Real de Medicina da Bélgica chegou a examinar o caso e concluiu que, do ponto de vista fisiológico, tal sobrevivência seria impossível.', 'Bois-d''Haine, Bélgica', '1868-1871', NULL, 'https://eucharisticmiracles.faith/miracle/anne-louise-lateau-eucharistic-fasting'),
  ('Eucharistic Miracles in the Life of Blessed Mary of the Passion San Giorgio a Cremano', 'Em 1866-1912, em Cremano, Itália, a pessoa teria vivido por anos alimentando-se apenas da Eucaristia.', 'A Beata Maria da Paixão (Maria Grazia Tarallo, 1866-1912), religiosa napolitana fundadora das Irmãs Crucificadas Adoradoras da Eucaristia, dedicou a vida à adoração eucarística e, em seus últimos dias, deixou de se alimentar por completo, sustentando-se apenas pela Sagrada Comunhão.', 'Cremano, Itália', '1866-1912', NULL, 'https://eucharisticmiracles.faith/miracle/blessed-mary-passion-eucharistic-life'),
  ('Our Lady of Good Help (Champion) Champion', 'Em 1859, em Champion, Estados Unidos, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Em outubro de 1859, a Virgem Maria apareceu três vezes à imigrante belga Adele Brise em Champion, no estado americano de Wisconsin — a única aparição mariana nos Estados Unidos já aprovada por um bispo diocesano. A mensagem tinha um apelo eucarístico direto: pedia confissão geral e Comunhão pela conversão dos pecadores. Doze anos depois, os cinco acres de terreno consagrado do santuário permaneceram intocados pelo mesmo incêndio de Peshtigo que devastou tudo ao redor.', 'Champion, Estados Unidos', '1859', NULL, 'https://eucharisticmiracles.faith/miracle/usa-champion'),
  ('Onil', 'Em 1824, em Onil, Espanha, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Em 1824, uma hóstia consagrada foi roubada junto com o vaso de ouro que a guardava. Encontrada intacta em um campo, é venerada como incorrupta na igreja paroquial local desde então.', 'Onil, Espanha', '1824', NULL, 'https://eucharisticmiracles.faith/miracle/spa-onil'),
  ('Bordeaux', 'Em 1822, em Bordeaux, França, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Em 3 de fevereiro de 1822, durante a Bênção do Santíssimo Sacramento numa capela francesa, os presentes relataram ter visto Jesus aparecer visivelmente na hóstia exposta por cerca de vinte minutos.', 'Bordeaux, França', '1822', NULL, 'https://eucharisticmiracles.faith/miracle/fra-bordeaux'),
  ('Eucharistic Sustenance of Blessed Anne Catherine Emmerich Dülmen', 'Em 1811, em Dülmen, Alemanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'A Beata Ana Catarina Emmerich, mística alemã que também apresentava os estigmas, teria vivido mais de dez anos praticamente sem se alimentar de nada além da Eucaristia e água.', 'Dülmen, Alemanha', '1811', NULL, 'https://eucharisticmiracles.faith/miracle/anne-catherine-emmerich-eucharistic-sustenance'),
  ('Patierno', 'Em 1772, em Nápoles, Itália, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Em 1772, hóstias consagradas roubadas de uma igreja perto de Nápoles foram encontradas cerca de um mês depois, ainda intactas. Um processo eclesiástico local avaliou o caso e concluiu que a preservação tinha caráter milagroso.', 'Nápoles, Itália', '1772', NULL, 'https://eucharisticmiracles.faith/miracle/ita-patierno-naples'),
  ('São Gerardo Majella — Comunhão na infância', 'Em 1733, em Muro Lucano, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Quando ainda menino, São Gerardo Majella foi impedido de fazer a primeira Comunhão por ser considerado jovem demais. Segundo a tradição, o próprio Arcanjo Miguel apareceu e lhe trouxe a Comunhão.', 'Muro Lucano, Itália', '1733', NULL, 'https://eucharisticmiracles.faith/miracle/saint-gerard-majella-childhood'),
  ('Scala', 'Em 1732, em Scala, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Em 1732, durante um período de adoração das Quarenta Horas num mosteiro italiano, os sinais da Paixão de Cristo teriam aparecido sobre uma hóstia exposta e permanecido visíveis por três meses seguidos — episódio relatado pelas religiosas do local e por Santo Afonso de Ligório.', 'Scala, Itália', '1732', NULL, 'https://eucharisticmiracles.faith/miracle/ita-scala'),
  ('Siena', 'Em 1730, em Siena, Itália, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Em 1730, 351 hóstias consagradas foram roubadas de uma igreja de Siena. Recuperadas, permaneceram perfeitamente conservadas por quase 300 anos sem sinal algum de decomposição; 223 delas sobrevivem até hoje. Diversos estudos científicos já confirmaram que essa preservação contraria as leis naturais de deterioração da matéria orgânica.', 'Siena, Itália', '1730', 'https://commons.wikimedia.org/wiki/Special:FilePath/Basilica_di_San_Francesco_%28Siena%29.JPG', 'https://eucharisticmiracles.faith/miracle/ita-siena'),
  ('Comunhões do Anjo da Guarda de Santa Maria Francesca', 'Em 1715-1791, em Nápoles, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'A napolitana Santa Maria Francisca das Cinco Chagas passava longos períodos acamada por causa dos estigmas. Conta-se que o próprio Anjo da Guarda lhe trazia a Comunhão, enquanto sacerdotes relatavam ver parte da hóstia e do vinho consagrados desaparecerem durante suas missas.', 'Nápoles, Itália', '1715-1791', NULL, 'https://eucharisticmiracles.faith/miracle/saint-maria-francesca-five-wounds'),
  ('Miraculous Communion of Saint Lucia Filippini Pitigliano', 'Em cerca de 1700, em Pitigliano, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Durante uma celebração, um fragmento de hóstia teria escapado das mãos do sacerdote e voado pelo ar, irradiando luz, até pousar sobre a língua de Santa Lúcia Filippini.', 'Pitigliano, Itália', 'cerca de 1700', NULL, 'https://eucharisticmiracles.faith/miracle/saint-lucia-filippini-pitigliano'),
  ('Aparições do Menino Jesus ao Beato Tomás de Cori', 'Em 1677-1729, em Orvieto, Itália, testemunhas relataram ter visto um rosto ou imagem de Cristo na hóstia exposta.', 'O frade franciscano Beato Tomás de Cori relatou diversas aparições do Menino Jesus durante a celebração da missa, especialmente no momento da consagração.', 'Orvieto, Itália', '1677-1729', NULL, 'https://eucharisticmiracles.faith/miracle/blessed-thomas-cori-apparitions'),
  ('Les Ulmes', 'Em 1668, em Les Ulmes, França, houve relato de aparição ou visão associada à Eucaristia.', 'Em 2 de junho de 1668, durante um período de adoração eucarística numa igreja francesa, os fiéis presentes viram na hóstia exposta a figura de um homem com túnica branca e as mãos cruzadas, visão que durou cerca de quinze minutos.', 'Les Ulmes, França', '1668', NULL, 'https://eucharisticmiracles.faith/miracle/fra-les-ulmes'),
  ('Montserrat', 'Em 1657, em Montserrat, Espanha, a hóstia sobreviveu a um incêndio que destruiu o local ao redor.', 'Entre 1653 e 1657, uma menina de apenas cinco anos relatou ver, durante três missas diferentes, a alma de seu pai falecido no purgatório — primeiro envolta em chamas e, na última vez, já vestida de branco, sinal de que havia alcançado o Céu.', 'Montserrat, Espanha', '1657', NULL, 'https://eucharisticmiracles.faith/miracle/spa-montserrat'),
  ('Cava dei Tirreni', 'Em 1656, em Cava de'' Tirreni, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Durante a epidemia de peste de 1656, Dom Angelo Franco abençoou a cidade italiana de Cava de'' Tirreni com o Santíssimo Sacramento a partir do Monte Castello. A tradição local atribui a esse gesto o fim da epidemia na região.', 'Cava de'' Tirreni, Itália', '1656', NULL, 'https://eucharisticmiracles.faith/miracle/ita-cava-dei-tirreni'),
  ('Eten', 'Em 1649, em Eten, Peru, testemunhas relataram ter visto um rosto ou imagem de Cristo na hóstia exposta.', 'Numa hóstia exposta à adoração pública no Peru, fiéis relataram ver aparecer a imagem do Menino Jesus e de três corações entrelaçados, em múltiplas ocasiões testemunhadas por diferentes pessoas.', 'Eten, Peru', '1649', NULL, 'https://eucharisticmiracles.faith/miracle/eten-peru-1649'),
  ('Pressac', 'Em 1643, em Pressac, França, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Depois de um incêndio em 1643, o copo de um cálice de estanho derreteu completamente com o calor — mas a hóstia consagrada guardada dentro dele permaneceu intacta sob uma bolha do metal derretido.', 'Pressac, França', '1643', NULL, 'https://eucharisticmiracles.faith/miracle/fra-pressac'),
  ('Turin', 'Em 1640, em Turin, Itália, a hóstia sobreviveu a um incêndio que destruiu o local ao redor.', 'Em 1640, um soldado francês que tentava profanar hóstias consagradas teria sido queimado por chamas que saíram do próprio recipiente sagrado (o cibório) onde elas estavam guardadas.', 'Turin, Itália', '1640', NULL, 'https://eucharisticmiracles.faith/miracle/ita-turin-1640'),
  ('O milagre de Calanda', 'Em 1640, em Calanda, Espanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Considerado "o milagre dos milagres", o caso envolve Miguel Juan Pellicer, que teve a perna amputada e, dois anos e meio depois, viu-a restaurada. A sentença canônica de 1641 atribuiu a cura à intercessão de Nossa Senhora do Pilar, em Zaragoza.', 'Calanda, Espanha', '1640', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bas%C3%ADlica_de_Nuestra_Se%C3%B1ora_del_Pilar%2C_Zaragoza.JPG', 'https://eucharisticmiracles.faith/miracle/calanda-miracle-1640'),
  ('Dronero', 'Em 1631, em Dronero, Itália, a hóstia sobreviveu a um incêndio que destruiu o local ao redor.', 'Em 3 de agosto de 1631, um incêndio que já havia destruído dezoito casas num bairro da cidade italiana de Dronero parou de se espalhar depois que um frade capuchinho o abençoou com o Santíssimo Sacramento.', 'Dronero, Itália', '1631', NULL, 'https://eucharisticmiracles.faith/miracle/ita-dronero'),
  ('Canosio', 'Em 1630, em Canosio, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Em 1630, o padre Antonio Reinardi deteve uma enchente catastrófica abençoando as águas com o Santíssimo Sacramento, salvando a vila italiana de Canosio da destruição total.', 'Canosio, Itália', '1630', NULL, 'https://eucharisticmiracles.faith/miracle/ita-canosio'),
  ('Santa Pudenciana', 'Em 1610, em Roma, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1610, um padre que duvidava da presença real de Cristo na Eucaristia deixou cair a hóstia durante a missa, deixando uma mancha de sangue nos degraus de mármore da igreja — mancha que, segundo relatos, ainda é visível hoje.', 'Roma, Itália', '1610', NULL, 'https://eucharisticmiracles.faith/miracle/ita-rome-1610'),
  ('Faverney', 'Em 1608, em Faverney, França, a hóstia sobreviveu a um incêndio que destruiu o local ao redor.', 'Um incêndio destruiu o altar de uma igreja francesa em 1608, mas o ostensório com o Santíssimo Sacramento permaneceu suspenso no ar por 33 horas, diante de mais de mil testemunhas.', 'Faverney, França', '1608', NULL, 'https://eucharisticmiracles.faith/miracle/fra-faverney'),
  ('Mogoro', 'Em 1604, em Mogoro, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Em 1604, dois homens em pecado mortal deixaram cair hóstias consagradas que, segundo relatos, deixaram marcas permanentes gravadas na pedra onde caíram.', 'Mogoro, Itália', '1604', NULL, 'https://eucharisticmiracles.faith/miracle/ita-mogoro'),
  ('Alcalá de Henares', 'Em 1597, em Alcalá de Henares, Espanha, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Hóstias consagradas roubadas permaneceram intactas enquanto hóstias não consagradas guardadas junto a elas se decompunham normalmente — uma diferença que os fiéis da época consideraram prova da presença real de Cristo. A relíquia foi perdida em 1936.', 'Alcalá de Henares, Espanha', '1597', NULL, 'https://eucharisticmiracles.faith/miracle/alcala-1597'),
  ('Pibrac', 'Em cerca de 1589-1600, em Pibrac, França, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Conta-se que as águas de um riacho violento se dividiram milagrosamente para permitir que Santa Germana Cousin, uma jovem pastora francesa, pudesse atravessá-lo e não perder a missa.', 'Pibrac, França', 'cerca de 1589-1600', NULL, 'https://eucharisticmiracles.faith/miracle/pibrac-eucharistic-miracle'),
  ('Gorkum-Escorial Gorinchem', 'Em 1572, em Gorinchem, Países Baixos, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1572, durante um conflito religioso na cidade de Gorkum, um atacante pisoteou uma hóstia consagrada com botas cravejadas de pregos, perfurando-a em três pontos — e dela teriam saído gotas de sangue. A hóstia acabou chegando às mãos do rei Filipe II da Espanha e permanece até hoje no Mosteiro de El Escorial, conhecida como a Sagrada Forma.', 'Gorinchem, Países Baixos', '1572', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cl.Coello.La_Sagrada_Forma.1685-90.Sacristy%2C_El_Escorial.jpg', 'https://eucharisticmiracles.faith/miracle/gorkum-escorial-1572'),
  ('Veroli', 'Em 1570, em Veroli, Itália, testemunhas relataram ter visto um rosto ou imagem de Cristo na hóstia exposta.', 'Em 1570, durante um período de adoração das Quarenta Horas, os fiéis relataram ver o Menino Jesus aparecer sobre a hóstia exposta numa igreja italiana.', 'Veroli, Itália', '1570', NULL, 'https://eucharisticmiracles.faith/miracle/ita-veroli'),
  ('Alcoy', 'Em 1568, em Alcoy, Espanha, testemunhas relataram ter visto um rosto ou imagem de Cristo na hóstia exposta.', 'Depois de hóstias consagradas serem roubadas de uma igreja espanhola, uma imagem do Menino Jesus teria apontado milagrosamente para o local onde estavam escondidas, levando à sua recuperação.', 'Alcoy, Espanha', '1568', NULL, 'https://eucharisticmiracles.faith/miracle/spa-alcoy'),
  ('Comunhão milagrosa de Santo Estanislau Kostka', 'Em 1567, em Viena, Áustria, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Gravemente doente e hospedado numa casa luterana de Viena que se recusava a permitir a entrada do Santíssimo Sacramento, Santo Estanislau Kostka teria recebido a Comunhão diretamente das mãos de Santa Bárbara, acompanhada por dois anjos.', 'Viena, Áustria', '1567', NULL, 'https://eucharisticmiracles.faith/miracle/saint-stanislaus-kostka-communion'),
  ('Morrovalle', 'Em 1560, em Morrovalle, Itália, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Em 1560, uma hóstia sobreviveu a um incêndio que destruiu por completo uma igreja franciscana italiana e derreteu até o cibório de prata onde ela estava guardada.', 'Morrovalle, Itália', '1560', NULL, 'https://eucharisticmiracles.faith/miracle/ita-morrovalle'),
  ('Asti', 'Em 1535, em Asti, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 25 de julho de 1535, sangue jorrou visivelmente da hóstia consagrada durante a missa, diante de toda a congregação reunida na cidade italiana de Asti. O Papa Paulo III chegou a conceder indulgência a quem visitasse a igreja no aniversário do episódio.', 'Asti, Itália', '1535', NULL, 'https://eucharisticmiracles.faith/miracle/ita-asti'),
  ('Marseille-En-Beauvais Marseille-en-Beauvaisis', 'Em 1533, em Marseille-en-Beauvaisis, França, a hóstia havia sido roubada ou profanada antes do fenômeno relatado.', 'Hóstias roubadas e abandonadas sob uma pedra em dezembro de 1532 foram encontradas em perfeito estado durante uma nevasca, no dia 1º de janeiro de 1533 — com o detalhe de que a pedra que as protegia havia permanecido sem neve, ao contrário de tudo ao redor.', 'Marseille-en-Beauvaisis, França', '1533', NULL, 'https://eucharisticmiracles.faith/miracle/fra-marseille-en-beauvais'),
  ('Ponferrada', 'Em 1533, em Ponferrada, Espanha, a hóstia havia sido roubada ou profanada antes do fenômeno relatado.', 'Em 1533, um sacrário roubado da Igreja de São Pedro foi jogado num arbusto de espinhos nos arredores de Ponferrada, na Espanha. Luzes noturnas e pombas brancas avistadas no local teriam guiado os moradores até a recuperação das hóstias consagradas.', 'Ponferrada, Espanha', '1533', NULL, 'https://eucharisticmiracles.faith/miracle/spa-ponferrada'),
  ('Nossa Senhora de Guadalupe', 'Em 1531, em Cidade do México, México, o episódio está associado a uma cura considerada extraordinária.', 'A Virgem Maria apareceu ao indígena mexicano Juan Diego na colina do Tepeyac, deixando uma imagem miraculosa gravada em seu manto (tilma) e curando seu tio doente. Mais de 490 anos depois, a tilma continua preservada, e a formação da imagem nela segue sem explicação científica. O episódio integra a exposição de milagres eucarísticos porque desencadeou conversões em massa e um aprofundamento da fé eucarística em toda a região.', 'Cidade do México, México', '1531', 'https://commons.wikimedia.org/wiki/Special:FilePath/1531_Nuestra_Se%C3%B1ora_de_Guadalupe_anagoria.jpg', 'https://eucharisticmiracles.faith/miracle/our-lady-of-guadalupe-1531'),
  ('Salzano', 'Em 1517, em Salzano, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Em 1517, na Itália, jumentos que carregavam viajantes teriam se ajoelhado espontaneamente diante do Santíssimo Sacramento sendo levado a um doente — um sinal, segundo a tradição, de que até os animais reconheceram a presença real de Cristo.', 'Salzano, Itália', '1517', NULL, 'https://eucharisticmiracles.faith/miracle/ita-salzano'),
  ('Volterra', 'Em 1472, em Volterra, Itália, relatos indicam que a hóstia ou o objeto sagrado se elevou no ar diante dos presentes.', 'Durante o saque da cidade italiana de Volterra em 1472, um soldado tomou de uma igreja o recipiente com hóstias consagradas e o destruiu num acesso de fúria. As hóstias, no entanto, permaneceram intactas. As fontes históricas divergem sobre qual igreja foi o palco do episódio e sobre se as hóstias caíram no chão ou se elevaram no ar.', 'Volterra, Itália', '1472', NULL, 'https://eucharisticmiracles.faith/miracle/ita-volterra'),
  ('St. Nicholas of Flüe Eucharistic Fasting Sachseln', 'Em 1467-1487, em Sachseln, Suíça, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'São Nicolau de Flüe viveu quase vinte anos como eremita na Suíça sem se alimentar de comida comum; sua sobrevivência é atribuída à Eucaristia, que recebia regularmente.', 'Sachseln, Suíça', '1467-1487', NULL, 'https://eucharisticmiracles.faith/miracle/st-nicholas-of-flue-eucharistic-fasting'),
  ('Incêndio de Meerssen', 'Em 1465, em Meerssen, Países Baixos, a hóstia sobreviveu a um incêndio que destruiu o local ao redor.', 'Um agricultor de um povoado holandês teria carregado o Santíssimo Sacramento para fora de uma igreja em chamas, sem sofrer qualquer ferimento apesar do incêndio ao seu redor.', 'Meerssen, Países Baixos', '1465', NULL, 'https://eucharisticmiracles.faith/miracle/meerssen-1465-fire'),
  ('La Rochelle', 'Em 1461, em La Rochelle, França, o episódio está associado a uma cura considerada extraordinária.', 'Em 1461, um menino de doze anos que estava paralisado e mudo desde os sete foi curado instantaneamente ao receber a primeira Comunhão no Domingo de Páscoa, na cidade francesa de La Rochelle.', 'La Rochelle, França', '1461', NULL, 'https://eucharisticmiracles.faith/miracle/fra-la-rochelle'),
  ('Turin', 'Em 1453, em Turin, Itália, relatos indicam que a hóstia ou o objeto sagrado se elevou no ar diante dos presentes.', 'Segundo relatos escritos um século depois dos fatos, uma hóstia roubada caiu de uma mula durante o transporte e se ergueu no ar, brilhando como o sol, antes de descer sozinha até o cálice segurado pelo bispo de Turim.', 'Turin, Itália', '1453', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chiesa_Corpus_Domini_Torino.JPG', 'https://eucharisticmiracles.faith/miracle/ita-turin-1453'),
  ('Ettiswil', 'Em 1447, em Ettiswil, Suíça, a hóstia sobreviveu a um incêndio que destruiu o local ao redor.', 'Em maio de 1447, uma hóstia consagrada foi levada da igreja paroquial de Ettiswil, na Suíça, e encontrada no dia seguinte num canteiro de urtigas fora da vila — segundo a tradição, partida em sete pedaços e envolta em luz. Uma mulher chamada Anna Vögtlin confessou o roubo sob interrogatório e acabou executada como bruxa. No local do achado foi erguida uma capela que se tornou destino de peregrinação e que permanece de pé até hoje.', 'Ettiswil, Suíça', '1447', NULL, 'https://eucharisticmiracles.faith/miracle/ettiswill-1447'),
  ('Avignon', 'Em 1433, em Avignon, França, relatos indicam que a hóstia ou o objeto sagrado se elevou no ar diante dos presentes.', 'Durante uma enchente em 1433, os rios Ródano e Durance invadiram uma capela na cidade francesa de Avignon, mas, segundo relatos da época, deixaram seco o corredor central ao redor de onde o Santíssimo Sacramento estava exposto.', 'Avignon, França', '1433', NULL, 'https://eucharisticmiracles.faith/miracle/fra-avignon'),
  ('Dijon', 'Em 1430, em Dijon, França, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Segundo a tradição, uma mulher cortou uma hóstia com uma faca em 1430, fazendo-a sangrar. O sangue, ao secar, deixou gravada a imagem de Jesus sentado num trono, cercado dos instrumentos de sua Paixão.', 'Dijon, França', '1430', NULL, 'https://eucharisticmiracles.faith/miracle/fra-dijon'),
  ('Alkmaar', 'Em 1429, em Alkmaar, Países Baixos, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Durante a primeira missa celebrada pelo padre recém-ordenado Folkert, um pouco do vinho consagrado se derramou; relatos da época indicam que vestígios com aparência de sangue foram encontrados depois em sua casula.', 'Alkmaar, Países Baixos', '1429', NULL, 'https://eucharisticmiracles.faith/miracle/alkmaar-1429'),
  ('Zaragoza', 'Em 1427, em Zaragoza, Espanha, testemunhas relataram ter visto um rosto ou imagem de Cristo na hóstia exposta.', 'Uma hóstia consagrada, roubada para ser usada num filtro de amor, revelou a imagem do Menino Jesus — que teria permanecido ileso mesmo depois de ser jogado ao fogo.', 'Zaragoza, Espanha', '1427', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bas%C3%ADlica_de_Nuestra_Se%C3%B1ora_del_Pilar%2C_Zaragoza.JPG', 'https://eucharisticmiracles.faith/miracle/spa-zaragoza'),
  ('Carmelite Monastery Eucharistic Miracle near Siena Siena', 'Em 1423, em Siena, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Um painel de retábulo pintado por Sassetta na década de 1420 retrata um monge carmelita caindo morto diante do altar enquanto lhe é oferecida uma hóstia sangrando e um demônio leva sua alma. Não há registro histórico de um episódio real por trás dessa cena, que parece ter função mais catequética do que factual.', 'Siena, Itália', '1423', NULL, 'https://eucharisticmiracles.faith/miracle/siena-carmelite-monk-miracle'),
  ('Bergen op Zoom', 'Em 1421, em Bergen op Zoom, Países Baixos, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Água do mar que havia encharcado hóstias consagradas durante a grande enchente de Santa Isabel, em 1421, deixou meses depois um resíduo de coloração avermelhada sobre elas.', 'Bergen op Zoom, Países Baixos', '1421', NULL, 'https://eucharisticmiracles.faith/miracle/bergen-netherlands-1421'),
  ('Guadalupe', 'Em 1420, em Guadalupe, Espanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1420, tomado pela dúvida sobre a transubstanciação, o frade Pedro de Cabañuelas teria visto a hóstia suspensa sobre o cálice no momento da consagração, derramando sangue sobre o corporal e a pala usados na missa. Ambos os panos são preservados até hoje no Real Mosteiro de Santa Maria de Guadalupe, na Espanha.', 'Guadalupe, Espanha', '1420', NULL, 'https://eucharisticmiracles.faith/miracle/spa-guadalupe'),
  ('Erding', 'Em 1417, em Erding, Alemanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Na Quinta-feira Santa de 1417, um camponês roubou uma hóstia na esperança de que lhe trouxesse riqueza. Ela teria se erguido de suas mãos por três vezes até desaparecer; uma capela foi construída no local onde, segundo a tradição, ela veio a repousar.', 'Erding, Alemanha', '1417', NULL, 'https://eucharisticmiracles.faith/miracle/ger-erding'),
  ('Herentals', 'Em 1412, em Herentals, Bélgica, a hóstia havia sido roubada ou profanada antes do fenômeno relatado.', 'Em 1412, cinco hóstias consagradas roubadas de uma igreja perto de Herentals, na Bélgica, e escondidas numa toca de coelho, foram encontradas intactas oito dias depois — mesmo tendo ficado expostas à chuva e à neve.', 'Herentals, Bélgica', '1412', NULL, 'https://eucharisticmiracles.faith/miracle/bel-herentals'),
  ('Bagno di Romagna', 'Em 1412, em Bagno di Romagna, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1412, um padre que duvidava da presença real de Cristo viu o vinho consagrado se transformar em sangue vivo, que escorreu sobre o corporal durante a missa. Uma análise química feita em 1958 confirmou que as manchas eram de natureza hemática.', 'Bagno di Romagna, Itália', '1412', NULL, 'https://eucharisticmiracles.faith/miracle/ita-bagno-di-romagna'),
  ('Weiten-Raxendorf', 'Em 1411, em Weiten-Raxendorf, Áustria, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1411, um ladrão escondeu uma hóstia roubada dentro de sua luva; seu cavalo simplesmente parou e se recusou a andar. A hóstia caiu sem que ele percebesse, e dias depois um transeunte a encontrou envolta em luz intensa, partida ao meio mas ainda ligada por fios de carne sangrando.', 'Weiten-Raxendorf, Áustria', '1411', NULL, 'https://eucharisticmiracles.faith/miracle/aut-weiten-raxendorf'),
  ('Ludbreg', 'Em 1411, em Ludbreg, Croácia, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1411, um padre que duvidava da presença real viu o vinho se transformar visivelmente em sangue durante a missa. O Precioso Sangue é venerado até hoje na cidade croata de Ludbreg havia mais de 600 anos.', 'Ludbreg, Croácia', '1411', NULL, 'https://eucharisticmiracles.faith/miracle/cro-ludbreg'),
  ('Bois-Seigneur-Isaac', 'Em 1405, em Bois-Seigneur-Isaac, Bélgica, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1405, um padre belga encontrou um fragmento de hóstia consagrada deixado sobre o corporal de uma missa anterior. Ao tentar removê-lo, o fragmento começou a sangrar, manchando o pano — que permanece preservado até hoje.', 'Bois-Seigneur-Isaac, Bélgica', '1405', NULL, 'https://eucharisticmiracles.faith/miracle/bel-bois-seigneur-isaac'),
  ('Boxmeer', 'Em 1400, em Boxmeer, Países Baixos, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Durante a missa de 1400, o vinho se transformou em sangue e transbordou do cálice sobre o corporal, depois que o padre celebrante expressou dúvida sobre a presença real de Cristo.', 'Boxmeer, Países Baixos', '1400', NULL, 'https://eucharisticmiracles.faith/miracle/boxmeer-1400'),
  ('Poznan Poznań', 'Em 1399, em Poznań, Polônia, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Por volta de 1399, uma hóstia consagrada encontrada num prado nos arredores de Poznań, na Polônia, deu origem a um forte culto eucarístico popular, levando à fundação de uma igreja carmelita dedicada ao Corpus Christi no local. A lenda posterior — de que três hóstias teriam sido roubadas, perfuradas e deixadas para sangrar — não aparece nas fontes medievais, e a própria Arquidiocese de Poznań afirma nunca ter confirmado essa versão.', 'Poznań, Polônia', '1399', NULL, 'https://eucharisticmiracles.faith/miracle/pol-poznan'),
  ('Moncada', 'Em 1392, em Moncada, Espanha, testemunhas relataram ter visto um rosto ou imagem de Cristo na hóstia exposta.', 'Durante o Cisma do Ocidente, em 1392, o Menino Jesus teria aparecido numa hóstia consagrada para confirmar a validade da ordenação de um padre espanhol — episódio testemunhado pela menina Inés Pedrós Alpicat, venerada na região valenciana como a Venerável Inés de Moncada.', 'Moncada, Espanha', '1392', NULL, 'https://eucharisticmiracles.faith/miracle/spa-moncada'),
  ('Seefeld', 'Em 1384, em Seefeld, Áustria, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1384, um cavaleiro orgulhoso exigiu receber uma hóstia grande demais durante a Comunhão. Segundo a tradição, o chão cedeu sob seus pés e a hóstia começou a sangrar.', 'Seefeld, Áustria', '1384', NULL, 'https://eucharisticmiracles.faith/miracle/aut-seefeld'),
  ('Wilsnack', 'Em 1383, em Wilsnack, Alemanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1383, três hóstias consagradas sobreviveram a um incêndio devastador e foram encontradas intactas, com gotas de sangue visíveis. O episódio transformou a cidade alemã de Wilsnack em um dos maiores centros de peregrinação da Europa medieval, até que a relíquia fosse destruída em 1552, durante a Reforma Protestante.', 'Wilsnack, Alemanha', '1383', NULL, 'https://eucharisticmiracles.faith/miracle/ger-wilsnack'),
  ('Boxtel-Hoogstraten Boxtel', 'Em 1380, em Boxtel, Países Baixos, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Vinho branco consagrado, derramado acidentalmente durante a missa, transformou-se em sangue, deixando manchas permanentes no corporal e na toalha do altar.', 'Boxtel, Países Baixos', '1380', NULL, 'https://eucharisticmiracles.faith/miracle/boxtel-hoogstraten-1380'),
  ('Middleburg-Lovanio Middleburg', 'Em 1374, em Middleburg, Países Baixos, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Durante a distribuição da Comunhão na cidade holandesa de Middelburg, a hóstia consagrada teria se transformado em carne sangrando ao ser recebida por um servo chamado Jan.', 'Middleburg, Países Baixos', '1374', NULL, 'https://eucharisticmiracles.faith/miracle/middleburg-lovanio-1374'),
  ('Brussels', 'Em 1370, em Brussels, Bélgica, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1370, judeus de Bruxelas foram falsamente acusados de roubar e esfaquear hóstias consagradas que teriam sangrado, e vários deles foram queimados na fogueira. A Igreja já repudiou publicamente essa acusação como infundada.', 'Brussels, Bélgica', '1370', NULL, 'https://eucharisticmiracles.faith/miracle/bel-brussels'),
  ('Cimballa', 'Em 1370, em Cimballa, Espanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Por volta de 1370, um padre que duvidava da presença real viu sangue escorrer da hóstia durante a missa, manchando o corporal, embora a própria hóstia permanecesse intacta. Abalado, ele decidiu se recolher a um mosteiro em penitência pelo resto da vida.', 'Cimballa, Espanha', '1370', NULL, 'https://eucharisticmiracles.faith/miracle/spa-cimballa'),
  ('Macerata', 'Em 1356, em Macerata, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1356, um padre que duvidava da presença real viu sangue fluir da hóstia no momento da fração do pão durante a missa.', 'Macerata, Itália', '1356', NULL, 'https://eucharisticmiracles.faith/miracle/ita-macerata'),
  ('Alboraya-Almácera', 'Em 1348, em Alboraya-Almácera, Espanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Segundo a tradição espanhola, peixes teriam resgatado hóstias consagradas que caíram num canal inundado, devolvendo-as a um padre ao segurá-las delicadamente na boca.', 'Alboraya-Almácera, Espanha', '1348', NULL, 'https://eucharisticmiracles.faith/miracle/alboraya-almacera-1348'),
  ('Amsterdam', 'Em 1345, em Amsterdam, Países Baixos, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Uma hóstia consagrada, jogada ao fogo de uma lareira, foi encontrada intacta entre as cinzas na manhã seguinte — episódio que deu origem a uma das devoções mais duradouras da cidade de Amsterdã.', 'Amsterdam, Países Baixos', '1345', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mirakel_van_Amsterdam%2C_gravure_J._Walter_%28coll._Catharijne_Convent%29.jpg', 'https://eucharisticmiracles.faith/miracle/amsterdam-1345'),
  ('Stiphout', 'Em 1342, em Stiphout, Países Baixos, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Hóstias consagradas escaparam ilesas das chamas que tomaram conta de uma igreja paroquial depois de ser atingida por um raio.', 'Stiphout, Países Baixos', '1342', NULL, 'https://eucharisticmiracles.faith/miracle/stiphout-1342'),
  ('Comunhão milagrosa da Beata Imelda Lambertini', 'Em 1333, em Bologna, Itália, relatos indicam que a hóstia ou o objeto sagrado se elevou no ar diante dos presentes.', 'Uma hóstia irradiando luz teria se erguido sozinha e parado diante da menina Imelda Lambertini, de apenas 11 anos, que morreu logo depois de recebê-la — episódio interpretado como sinal de sua profunda união com Cristo.', 'Bologna, Itália', '1333', NULL, 'https://eucharisticmiracles.faith/miracle/blessed-imelda-lambertini-bologna'),
  ('Blanot', 'Em 1331, em Blanot, França, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Durante a missa de Páscoa de 1331, um fragmento de hóstia caiu e foi encontrado transformado em sangue, manchando o corporal. Por mais que tentassem lavar o pano, a mancha só ficava mais escura e maior.', 'Blanot, França', '1331', NULL, 'https://eucharisticmiracles.faith/miracle/fra-blanot'),
  ('Walldürn', 'Em 1330, em Walldürn, Alemanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1330, o Precioso Sangue derramado durante a missa formou, na toalha do altar, uma imagem de Cristo crucificado e onze imagens menores de seu rosto coroado de espinhos — tornando-se uma das relíquias eucarísticas mais veneradas da Alemanha.', 'Walldürn, Alemanha', '1330', 'https://commons.wikimedia.org/wiki/Special:FilePath/Blutkorporale%2C_Walld%C3%BCrn_%28Germany%29.JPG', 'https://eucharisticmiracles.faith/miracle/ger-wallduern'),
  ('Cascia Siena', 'Em 1330, em Siena, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1330, na cidade de Siena, um padre carregou de forma inadequada uma hóstia dentro de seu breviário. Ela se transformou em sangue, manchando as páginas do livro; uma delas é preservada até hoje na cidade de Cascia.', 'Siena, Itália', '1330', NULL, 'https://eucharisticmiracles.faith/miracle/ita-cascia'),
  ('Herkenrode-Hasselt Herkenrode', 'Em 1317, em Herkenrode, Bélgica, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Uma hóstia tocada por um curioso em 1317 foi encontrada manchada de sangue. Ao chegar à Abadia de Herkenrode, os presentes relataram ver o rosto de Cristo se formar sobre sua superfície.', 'Herkenrode, Bélgica', '1317', NULL, 'https://eucharisticmiracles.faith/miracle/bel-herkenrode-hasselt'),
  ('Fiecht', 'Em 1310, em Fiecht, Áustria, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Durante a missa, o vinho consagrado por um padre que duvidava da presença real transformou-se em sangue e fervilhou, transbordando do cálice — e, segundo relatos, ainda parecia fresco 170 anos depois.', 'Fiecht, Áustria', '1310', NULL, 'https://eucharisticmiracles.faith/miracle/fiecht-austria-1310'),
  ('O''Cebreiro', 'Em cerca de 1300, em O''Cebreiro, Espanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Por volta do ano 1300, um monge que duvidava da presença real viu a hóstia se transformar em carne e o vinho em sangue durante a missa, depois que um agricultor enfrentou uma nevasca para não faltar à celebração — episódio que restaurou a fé do religioso.', 'O''Cebreiro, Espanha', 'cerca de 1300', NULL, 'https://eucharisticmiracles.faith/miracle/spa-ocebreiro'),
  ('Breda-Niervaart Breda', 'Em 1300, em Breda, Países Baixos, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Por volta de 1300, o agricultor holandês Jan Bautoen encontrou uma hóstia consagrada enterrada em uma turfeira perto de Niervaert, e ela sangrou ao ser retirada do solo. Com o avanço do mar sobre a região, a relíquia foi transferida em 1449 para a Grote Kerk de Breda, com autorização do bispo de Liège.', 'Breda, Países Baixos', '1300', NULL, 'https://eucharisticmiracles.faith/miracle/breda-niervaart-1300'),
  ('Comunhão angélica da Beata Emília Bicchieri', 'Em cerca de 1300, em Vercelli, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Um anjo teria trazido a Comunhão à fundadora Beata Emília Bicchieri no dia em que ela faltou à missa por estar cuidando de uma irmã doente.', 'Vercelli, Itália', 'cerca de 1300', NULL, 'https://eucharisticmiracles.faith/miracle/blessed-emilia-bicchieri-communion'),
  ('Gerona Girona', 'Em 1297, em Girona, Espanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1297, um padre que duvidava da presença real recebeu a hóstia na Comunhão e a sentiu se transformar em carne sangrando dentro da própria boca, sem conseguir engoli-la.', 'Girona, Espanha', '1297', NULL, 'https://eucharisticmiracles.faith/miracle/spa-gerona'),
  ('Visão eucarística da Beata Ângela de Foligno', 'Em 1296-1309, em Foligno, Itália, houve relato de aparição ou visão associada à Eucaristia.', 'Entre 1292 e 1296, a Beata Ângela de Foligno ditou ao seu confessor franciscano diversas visões místicas que teve. Em algumas delas, via Cristo dentro da hóstia consagrada — uma vez como dois olhos brilhantes, outra como um menino sentado em majestade, como um rei.', 'Foligno, Itália', '1296-1309', NULL, 'https://eucharisticmiracles.faith/miracle/foligno-blessed-angela-vision'),
  ('Gruaro (Valvasone)', 'Em 1294, em Gruaro, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Sangue escorreu de uma hóstia consagrada encontrada entre panos de altar que estavam sendo lavados em um tanque público na Itália.', 'Gruaro, Itália', '1294', NULL, 'https://eucharisticmiracles.faith/miracle/gruaro-valvasone-1294'),
  ('Paris', 'Em 1290, em Paris, França, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1290, um judeu parisiense chamado Jonathas foi acusado de esfaquear uma hóstia, que teria sangrado e resistido ao fogo e à água fervente antes de se erguer em forma de crucifixo. Ele foi julgado e condenado à morte. Historiadores consideram esse o primeiro caso totalmente documentado de acusação de profanação de hóstia contra judeus — um episódio hoje reconhecido como fruto de perseguição, não de fato histórico comprovado.', 'Paris, França', '1290', NULL, 'https://eucharisticmiracles.faith/miracle/fra-paris'),
  ('Glotowo Głotowo', 'Em 1290, em Głotowo, Polônia, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Um cibório escondido para protegê-lo de saqueadores foi encontrado anos depois, quando os bois de um agricultor se ajoelharam espontaneamente sobre o local. A hóstia lá dentro estava perfeitamente conservada, e uma capela dedicada ao Corpus Christi foi erguida ali.', 'Głotowo, Polônia', '1290', NULL, 'https://eucharisticmiracles.faith/miracle/pol-glotowo'),
  ('Beato Tiago de Montieri', 'Em morte em 1289, em Montieri, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Segundo a tradição toscana, o próprio Jesus Cristo teria dado a Comunhão diretamente ao Beato Tiago de Montieri, um recluso do século XIII.', 'Montieri, Itália', 'morte em 1289', NULL, 'https://eucharisticmiracles.faith/miracle/blessed-james-montieri-jesus-communion'),
  ('Kranenburg', 'Em 1280, em Kranenburg, Alemanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Segundo a tradição local, por volta de 1280 um pastor que não conseguiu engolir a hóstia na missa de Páscoa a escondeu dentro de uma árvore oca. Vinte e oito anos depois, quando a árvore foi derrubada, encontraram em seu interior um crucifixo de madeira.', 'Kranenburg, Alemanha', '1280', NULL, 'https://eucharisticmiracles.faith/miracle/ger-kranenburg'),
  ('Offida', 'Em 1273, em Offida, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1273, uma hóstia usada em um ritual de feitiçaria transformou-se em carne e sangrou quando uma mulher tentou queimá-la.', 'Offida, Itália', '1273', NULL, 'https://eucharisticmiracles.faith/miracle/ita-offida'),
  ('Bruges', 'Em 1270, em Bruges, Bélgica, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'A Basílica do Santo Sangue, em Bruges, guarda uma relíquia — um frasco de cristal de rocha que, segundo a tradição, contém sangue de Cristo. Os documentos mais antigos que mencionam a relíquia na cidade datam da década de 1250, e os relatos de uma liquefação semanal do sangue surgem já no início do século XIV.', 'Bruges, Bélgica', '1270', 'https://commons.wikimedia.org/wiki/Special:FilePath/The_Blood_Relic.jpg', 'https://eucharisticmiracles.faith/miracle/bel-bruges'),
  ('Comunhão milagrosa de Santa Inês de Segni', 'Em 1268-1317, em Proceno, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Santa Inês de Segni, dominicana, teria recebido a Comunhão das mãos de um anjo no dia em que faltou à missa por ter se prolongado em oração no jardim do mosteiro.', 'Proceno, Itália', '1268-1317', NULL, 'https://eucharisticmiracles.faith/miracle/proceno-saint-agnes-segni-communion'),
  ('Comunhão milagrosa de Santa Clara de Montefalco', 'Em 1268-1308, em Montefalco, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Santa Clara de Montefalco recebeu a Comunhão diretamente de Cristo depois que uma irmã a repreendeu por se aproximar sem o manto adequado e disse que ela não deveria comungar naquele dia.', 'Montefalco, Itália', '1268-1308', NULL, 'https://eucharisticmiracles.faith/miracle/montefalco-saint-clare-communion'),
  ('Bolsena', 'Em 1263, em Bolsena, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1263, um padre que duvidava da presença real teria visto sangue brotar da hóstia durante a missa na cidade italiana de Bolsena. A tradição associa esse episódio à instituição da festa de Corpus Christi pelo Papa Urbano IV no ano seguinte — para a qual encomendou a São Tomás de Aquino a redação da liturgia —, embora a própria bula papal não mencione Bolsena expressamente.', 'Bolsena, Itália', '1263', 'https://commons.wikimedia.org/wiki/Special:FilePath/Miracle_of_Bolsena.JPG', 'https://eucharisticmiracles.faith/miracle/ita-bolsena'),
  ('Precioso Sangue de Jesus — Neuvy-Saint-Sépulcre', 'Em 1257, em Neuvy-Saint-Sépulcre, França, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Duas gotas de sangue, ditas recolhidas no Calvário durante a Paixão de Cristo, foram enviadas da Itália aos cônegos de Neuvy-Saint-Sépulchre em 1257 pelo Cardeal Eudes de Châteauroux, legado papal na cruzada de São Luís, rei da França.', 'Neuvy-Saint-Sépulcre, França', '1257', NULL, 'https://eucharisticmiracles.faith/miracle/neuvy-saint-sepulcre-precious-blood'),
  ('Regensburg (Ratisbona)', 'Em 1255, em Regensburg, Alemanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Um padre que levava o Viático escorregou ao atravessar uma prancha sobre um riacho e deixou cair o cibório com as hóstias consagradas. Uma capela foi erguida no local, e a tradição conta que, mais tarde, um crucifixo teria tomado o cálice das mãos de um padre que duvidava da presença real.', 'Regensburg, Alemanha', '1255', NULL, 'https://eucharisticmiracles.faith/miracle/regensburg-dropped-hosts-1255'),
  ('Douai', 'Em 1254, em Douai, França, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1254, uma hóstia encontrada no chão se ergueu sozinha, e o rosto de uma criança apareceu no pano que ela tocou. Depois, a imagem foi se transformando até mostrar o rosto de Cristo coroado de espinhos, com sangue na testa.', 'Douai, França', '1254', NULL, 'https://eucharisticmiracles.faith/miracle/fra-douai'),
  ('San Juan de las Abadesas', 'Em 1251, em San Juan de las Abadesas, Espanha, a hóstia foi encontrada intacta, sem sinais de decomposição, mesmo após anos.', 'Uma hóstia consagrada colocada dentro de um crucifixo de madeira em 1251 foi descoberta 175 anos depois, ainda envolta em linho e há muito tempo descrita como incorrupta.', 'San Juan de las Abadesas, Espanha', '1251', NULL, 'https://eucharisticmiracles.faith/miracle/saint-john-of-the-abbesses-1251'),
  ('Santarém', 'Em 1247, em Santarém, Portugal, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Uma mulher que roubou uma hóstia a pedido de uma feiticeira testemunhou-a sangrar em suas próprias mãos. Diversos papas concederam indulgências ligadas a esse milagre, hoje preservado em um vaso de cristal na cidade portuguesa de Santarém.', 'Santarém, Portugal', '1247', 'https://commons.wikimedia.org/wiki/Special:FilePath/Milagre_Eucar%C3%ADstico_de_Santar%C3%A9m.png', 'https://eucharisticmiracles.faith/miracle/por-santarem'),
  ('Saint Clare of Assisi Assisi', 'Em cerca de 1240, em Assisi, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Por volta de 1240, Santa Clara de Assis fez recuar tropas sarracenas que ameaçavam o convento apenas orando diante do Santíssimo Sacramento exposto. Uma das religiosas presentes testemunhou ter ouvido uma voz prometendo proteção divina à comunidade.', 'Assisi, Itália', 'cerca de 1240', 'https://commons.wikimedia.org/wiki/Special:FilePath/Santa_Chiara_Assisi2.jpg', 'https://eucharisticmiracles.faith/miracle/ita-saint-clare-assisi'),
  ('Daroca', 'Em 1239, em Daroca, Espanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Durante uma batalha contra forças mouras em 1239, na Espanha, seis hóstias consagradas escondidas sob uma pedra foram encontradas manchadas de sangue e grudadas ao corporal de linho. O pano foi fixado numa lança como estandarte, e as tropas cristãs seguiram para tomar o castelo inimigo.', 'Daroca, Espanha', '1239', NULL, 'https://eucharisticmiracles.faith/miracle/spa-daroca'),
  ('Caravaca de la Cruz', 'Em 1231, em Caravaca de la Cruz, Espanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Segundo a tradição, em 1231 um padre cativo foi obrigado a celebrar missa diante do governante muçulmano de Caravaca. Sem crucifixo à mão, ele teria recebido uma cruz de duas travessas trazida por dois anjos; ao vê-la, o governante enxergou o Menino Jesus na hóstia e se converteu, pedindo o batismo.', 'Caravaca de la Cruz, Espanha', '1231', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bas%C3%ADlica_de_la_Vera_Cruz%2C_Caravaca_%281%29.jpg', 'https://eucharisticmiracles.faith/miracle/spa-caravaca-de-la-cruz'),
  ('Florence', 'Em 1230-1595, em Florence, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Dois episódios distintos são registrados na mesma igreja italiana: em 1230, vinho deixado num cálice teria sido encontrado transformado em sangue coagulado; já em 1595, hóstias consagradas sobreviveram a um incêndio e foram encontradas intactas quando examinadas em 1628.', 'Florence, Itália', '1230-1595', NULL, 'https://eucharisticmiracles.faith/miracle/ita-florence'),
  ('Alatri', 'Em 1228, em Alatri, Itália, exames posteriores identificaram tecido compatível com músculo cardíaco humano.', 'Em 1228, uma jovem levou uma hóstia consagrada a pedido de uma feiticeira. Três dias depois, ela foi encontrada transformada em carne, e a jovem confessou o ocorrido. O Papa Gregório IX chegou a escrever ao bispo de Alatri orientando a penitência a ser aplicada às duas mulheres envolvidas.', 'Alatri, Itália', '1228', NULL, 'https://eucharisticmiracles.faith/miracle/ita-alatri'),
  ('Rimini', 'Em 1227, em Rimini, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Segundo a tradição franciscana dos anos 1220, uma mula se ajoelhou diante da Eucaristia erguida por Santo Antônio de Pádua, convertendo um herege que havia desafiado publicamente a doutrina da presença real.', 'Rimini, Itália', '1227', NULL, 'https://eucharisticmiracles.faith/miracle/ita-rimini'),
  ('Meerssen', 'Em 1222-1465, em Meerssen, Países Baixos, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1222, sangue e água escorreram da hóstia consagrada durante o rito da fração do pão na missa, na cidade holandesa de Meerssen. O fragmento manchado foi guardado dentro do cálice, e o episódio foi registrado pelo cronista Cesário de Heisterbach.', 'Meerssen, Países Baixos', '1222-1465', NULL, 'https://eucharisticmiracles.faith/miracle/hol-meerssen'),
  ('Benningen', 'Em 1216, em Benningen, Alemanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Em 1216, um moleiro que havia guardado uma hóstia consagrada para incriminar um rival por sacrilégio viu-a sangrar em suas mãos. Ele acabou confessando o plano, e o bispo de Augsburgo preservou a hóstia.', 'Benningen, Alemanha', '1216', NULL, 'https://eucharisticmiracles.faith/miracle/ger-benningen'),
  ('Milagre Eucarístico do IV Concílio de Latrão', 'Em 1215, em Roma, Itália, relatos indicam que a hóstia ou o objeto sagrado se elevou no ar diante dos presentes.', 'Durante uma missa celebrada em Roma pelo Patriarca Maronita Jeremias II al-Amshitti, na presença do Papa Inocêncio III, a hóstia consagrada teria emitido luz e permanecido suspensa no ar depois que o patriarca abaixou as mãos.', 'Roma, Itália', '1215', NULL, 'https://eucharisticmiracles.faith/miracle/ita-rome-1215'),
  ('Os cordeiros devotos da Eucaristia', 'Em cerca de 1210-1220, em Roma, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'A biografia de São Francisco escrita por São Boaventura registra um cordeiro, em Roma, que acompanhava uma nobre até a igreja, e uma ovelha na Porciúncula que se inclinava no momento da elevação da hóstia — episódios lidos como sinais de que até os animais reconheciam a presença de Cristo.', 'Roma, Itália', 'cerca de 1210-1220', NULL, 'https://eucharisticmiracles.faith/miracle/devoted-lambs-eucharist'),
  ('Liège', 'Em 1208, em Liège, Bélgica, houve relato de aparição ou visão associada à Eucaristia.', 'Santa Juliana de Liège recebeu, no século XIII, visões de Cristo relacionadas à Eucaristia que a levaram a defender junto à Igreja a criação de uma festa dedicada ao Corpo de Cristo — pedido que resultaria na instituição do Corpus Christi.', 'Liège, Bélgica', '1208', NULL, 'https://eucharisticmiracles.faith/miracle/bel-liege'),
  ('Augsburg', 'Em 1194-1199, em Augsburg, Alemanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Uma mulher guardou em casa uma hóstia consagrada por cinco anos, até que, em 1199, ela foi descoberta transformada em carne sangrando, com finos filamentos conectando os pedaços.', 'Augsburg, Alemanha', '1194-1199', NULL, 'https://eucharisticmiracles.faith/miracle/ger-augsburg'),
  ('Ferrara', 'Em 1171, em Ferrara, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'No Domingo de Páscoa de 1171, sangue jorrou visivelmente da hóstia durante a missa, manchando a abóbada acima do altar na cidade italiana de Ferrara. As manchas permanecem visíveis até hoje, mais de 850 anos depois.', 'Ferrara, Itália', '1171', NULL, 'https://eucharisticmiracles.faith/miracle/ita-ferrara'),
  ('São Bernardo converte um duque com a Eucaristia', 'Em 1134, em Chiaravalle, Itália, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'São Bernardo de Claraval converteu o duque Guilherme X da Aquitânia, que estava excomungado, apresentando-lhe o Santíssimo Sacramento durante um encontro público — gesto que fez o duque cair de joelhos, arrependido.', 'Chiaravalle, Itália', '1134', NULL, 'https://eucharisticmiracles.faith/miracle/saint-bernard-chiaravalle-duke-conversion'),
  ('Bettbrunn', 'Em 1125, em Bettbrunn, Alemanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Segundo uma lenda registrada por escrito só por volta de 1420, uma hóstia consagrada carregada por um pastor caiu ao chão perto de Bettbrunn, na Alemanha, em 1125, e ninguém conseguiu levantá-la até a chegada do bispo de Regensburg. A capela erguida no local tornou-se um importante destino de peregrinação bávaro até hoje.', 'Bettbrunn, Alemanha', '1125', NULL, 'https://eucharisticmiracles.faith/miracle/ger-bettbrunn'),
  ('Weingarten', 'Em 1094, em Weingarten, Alemanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Uma relíquia com terra embebida em gotas do Precioso Sangue de Cristo, trazida da Terra Santa, é venerada na cidade alemã de Weingarten desde o final do século XI.', 'Weingarten, Alemanha', '1094', NULL, 'https://eucharisticmiracles.faith/miracle/ger-weingarten'),
  ('Valencia', 'Em 1055, em Valencia, Espanha, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'O Santo Cálice, uma taça de ágata venerada na Catedral de Valência como o próprio cálice usado por Jesus na Última Ceia, teria sido levado de Roma à Espanha ainda no século III, segundo a tradição, e está sob a guarda da catedral desde o século XV.', 'Valencia, Espanha', '1055', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chalice_of_Valencia.JPG', 'https://eucharisticmiracles.faith/miracle/spa-valencia'),
  ('São Pedro Damião — relato de Montecassino', 'Em 1050, em local não identificado, Itália, exames posteriores identificaram tecido compatível com músculo cardíaco humano.', 'São Pedro Damião registrou, a partir de cartas que recebeu do abade Desidério de Montecassino, o relato de uma hóstia que se transformou parcialmente em carne depois que uma mulher a guardou da Comunhão para usá-la num feitiço.', 'local não identificado, Itália', '1050', NULL, 'https://eucharisticmiracles.faith/miracle/ita-s-peter-damian'),
  ('Ivorra', 'Em 1010, em Ivorra, Espanha, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Por volta do ano 1010, durante a missa, o vinho se transformou em sangue e transbordou do cálice sobre a toalha do altar e o chão, convertendo um padre que até então duvidava da presença real. A tradição atribui ao Papa Sérgio IV a certificação do milagre.', 'Ivorra, Espanha', '1010', NULL, 'https://eucharisticmiracles.faith/miracle/spa-ivorra'),
  ('Lanciano', 'Em cerca de 750, em Lanciano, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'O mais antigo milagre eucarístico já documentado, investigado cientificamente em 1970 e 1971. A hóstia se transformou em tecido cardíaco e o vinho em sangue humano do tipo AB, ambos preservados intactos até os dias de hoje na cidade italiana de Lanciano.', 'Lanciano, Itália', 'cerca de 750', 'https://commons.wikimedia.org/wiki/Special:FilePath/Miracolo_Eucaristico_di_Lanciano_-_foto_dal_vivo.JPG', 'https://eucharisticmiracles.faith/miracle/ita-lanciano'),
  ('Santo Egídio (Saint-Gilles-du-Gard)', 'Em cerca de 720-730, em Saint-Gilles-du-Gard, França, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Durante uma missa celebrada por Santo Egídio, um anjo teria aparecido trazendo um livro com o pecado não confessado de Carlos Martel, líder franco — pecado que desapareceu milagrosamente das páginas, concedendo-lhe a absolvição.', 'Saint-Gilles-du-Gard, França', 'cerca de 720-730', NULL, 'https://eucharisticmiracles.faith/miracle/saint-egidio-charles-martel-absolution'),
  ('São Gregório Magno', 'Em 595, em Roma, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Por volta do ano 595, São Gregório Magno teria pedido um sinal a Deus durante a missa, e a hóstia teria tomado a aparência de carne ensanguentada do tamanho de um dedo, convertendo uma mulher que duvidava da presença real.', 'Roma, Itália', '595', NULL, 'https://eucharisticmiracles.faith/miracle/ita-rome-6th-7th'),
  ('Santa Maria do Egito — travessia do Jordão', 'Em cerca de 421, em Vale do Rio Jordão, Jordânia, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Santa Maria do Egito recebeu a Comunhão do monge Zósimo depois de atravessar o Rio Jordão a pé, sobre as águas, ao final de 47 anos de penitência solitária no deserto da Palestina do século V.', 'Vale do Rio Jordão, Jordânia', 'cerca de 421', NULL, 'https://eucharisticmiracles.faith/miracle/egy-st-mary-egypt'),
  ('Santo Sátiro — naufrágio no Mediterrâneo', 'Em cerca de 375, em local não identificado, Mar Mediterrâneo, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Santo Sátiro teria sido milagrosamente salvo de um naufrágio ao carregar a Eucaristia amarrada ao pescoço dentro de um pano.', 'local não identificado, Mar Mediterrâneo', 'cerca de 375', NULL, 'https://eucharisticmiracles.faith/miracle/saint-satyrus-shipwreck'),
  ('Trani', 'No século XI, em Trani, Itália, a hóstia consagrada, ou o vinho, apresentou sangramento visível durante a missa.', 'Uma hóstia colocada em óleo fervente teria se transformado em carne e sangrado; a relíquia é venerada na cidade italiana de Trani e foi descrita pela primeira vez no relato de um peregrino em 1470.', 'Trani, Itália', 'século XI', NULL, 'https://eucharisticmiracles.faith/miracle/ita-trani'),
  ('Scete', 'No século IV, em Scete, Egito, a Igreja local registrou um fenômeno considerado extraordinário ligado à Eucaristia.', 'Um monge do deserto egípcio que duvidava da presença real viu, junto com dois companheiros durante a liturgia, uma criança aparecer sobre o altar no lugar do pão — episódio registrado nos Ditos dos Padres do Deserto, um dos textos mais antigos da espiritualidade cristã.', 'Scete, Egito', 'século IV', NULL, 'https://eucharisticmiracles.faith/miracle/egy-scete')
) AS v(title, summary, content, location, event_date, image_url, source_url)
WHERE c.slug = 'milagres-eucaristicos';